/* TETTS independent float32 DSP. No WORLD, FFT, Python or neural runtime.
 * One frame lookahead, bounded context, complementary IIR noise bank and
 * minimum-phase FIR generated by cepstrum-to-impulse recursion.
 */
#define _POSIX_C_SOURCE 200809L
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#define MAX_TAPS 256
#define MAX_BANDS 5
#define MAX_DIM 32
#define HOP 160
#define RATE 16000

typedef struct {
    double excitation_cpu_s, filter_build_cpu_s, filtering_cpu_s, pcm_cpu_s;
    uint64_t bank_mac, fir_mac, basis_mac, recursion_mac, generated_samples, clipped_pcm;
    uint64_t exp_calls, sqrt_calls, context_bytes;
} TetStats;

typedef struct {
    float phase, carry, held_frequency;
    uint32_t rng[MAX_BANDS];
    float tone_state[MAX_BANDS-1][2];
    float noise_upper[MAX_BANDS][2],noise_lower[MAX_BANDS][2];
    float filter_a[MAX_TAPS],filter_b[MAX_TAPS],causal[MAX_TAPS];
    float history[2*MAX_TAPS],source[HOP];
    int history_pos;
} TetContext;

static double cpu_now(void) {
    struct timespec t;clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t);
    return (double)t.tv_sec + (double)t.tv_nsec*1e-9;
}
static float clip(float x,float lo,float hi){return x<lo?lo:x>hi?hi:x;}
static float white(uint32_t *state){
    uint32_t x=*state;x^=x<<13;x^=x>>17;x^=x<<5;*state=x;
    return ((float)((double)x/4294967296.0)*2.f-1.f)*1.7320508075688772f;
}
static float biquad(float x,const float *b,float *s){
    float y=b[0]*x+s[0];s[0]=b[1]*x-b[3]*y+s[1];s[1]=b[2]*x-b[4]*y;return y;
}
static void initialize(TetContext *c,uint32_t seed,int bands){
    memset(c,0,sizeof(*c));c->phase=1.f;c->held_frequency=120.f;
    for(int b=0;b<bands;b++)c->rng[b]=seed+104729u*(uint32_t)(b+1);
}
static void source_block(TetContext *c,const float *begin,const float *end,int dim,int bands,
                         const float *bank,int count,int harmonic_only,TetStats *stats){
    const int ap_offset=1+dim,vuv_offset=1+dim+bands;
    float f0=begin[0]>0?begin[0]:c->held_frequency;
    float f1=end[0]>0?end[0]:f0;
    if(end[0]>0)c->held_frequency=end[0];
    float height0=sqrtf(RATE/f0),height1=sqrtf(RATE/f1);
    float mean0=sqrtf(f0/RATE),mean1=sqrtf(f1/RATE);
    stats->sqrt_calls+=4;
    float a0[MAX_BANDS],a1[MAX_BANDS],p0[MAX_BANDS],p1[MAX_BANDS];
    for(int b=0;b<bands;b++){
        a0[b]=powf(10.f,3.f*clip(begin[ap_offset+b],-1.f,0.f));
        a1[b]=powf(10.f,3.f*clip(end[ap_offset+b],-1.f,0.f));
        p0[b]=sqrtf(fmaxf(0,1-a0[b]*a0[b]));p1[b]=sqrtf(fmaxf(0,1-a1[b]*a1[b]));
        stats->exp_calls+=2;stats->sqrt_calls+=2;
    }
    for(int n=0;n<count;n++){
        float a=(float)n/HOP,frequency=f0+(f1-f0)*a;
        float pulse=c->carry-(mean0+(mean1-mean0)*a);c->carry=0;
        float previous=c->phase;c->phase+=frequency/RATE;
        if(c->phase>=1.f){
            float fraction=previous>=1.f?0.f:clip((1.f-previous)/(frequency/RATE),0.f,1.f);
            float height=height0+(height1-height0)*a;
            pulse+=height*(1.f-fraction);c->carry=height*fraction;c->phase-=1.f;
        }
        float low[MAX_BANDS-1],band_period[MAX_BANDS];
        for(int j=0;j<bands-1;j++)low[j]=biquad(pulse,bank+5*j,c->tone_state[j]);
        band_period[0]=low[0];
        for(int b=1;b<bands-1;b++)band_period[b]=low[b]-low[b-1];
        band_period[bands-1]=pulse-low[bands-2];
        float mixture=0,broad=0;
        for(int b=0;b<bands;b++){
            float z=white(&c->rng[b]);if(b==0)broad=z;
            float upper=b==bands-1?z:biquad(z,bank+5*b,c->noise_upper[b]);
            float lower=b==0?0:biquad(z,bank+5*(b-1),c->noise_lower[b]);
            mixture+=(p0[b]+(p1[b]-p0[b])*a)*band_period[b]+(a0[b]+(a1[b]-a0[b])*a)*(upper-lower);
        }
        stats->bank_mac+=(uint64_t)(3*bands-3)*5;
        float voiced=clip(begin[vuv_offset]+(end[vuv_offset]-begin[vuv_offset])*a,0,1);
        if(harmonic_only)c->source[n]=voiced*pulse;
        else if(voiced<=0)c->source[n]=broad;
        else if(voiced>=1)c->source[n]=mixture;
        else{c->source[n]=sqrtf(voiced)*mixture+sqrtf(1-voiced)*broad;stats->sqrt_calls+=2;}
    }
}

static int build_filter(const float *frame,const float *basis,int dim,int length,
                         float *h,float *causal,TetStats *stats){
    for(int n=1;n<length;n++){
        float value=0;
        for(int j=0;j<dim-1;j++)value+=basis[n*(dim-1)+j]*frame[j+2];
        causal[n]=value;
    }
    h[0]=1.f;
    for(int n=1;n<length;n++){
        float value=0;
        for(int k=1;k<=n;k++)value+=(float)k*causal[k]*h[n-k];
        h[n]=value/(float)n;if(!isfinite(h[n]))return -2;
    }
    /* Gentle end taper, energy-normalized from the retained log-energy channel. */
    float energy=0;
    for(int n=0;n<length;n++){
        if(n>=(3*length)/4){float t=(float)(length-n)/(float)(length/4);h[n]*=t*t*(3-2*t);}
        energy+=h[n]*h[n];
    }
    float target=expf(clip(frame[1],-40.f,20.f));float scale=sqrtf(target/fmaxf(energy,1e-30f));
    for(int n=0;n<length;n++)h[n]*=scale;
    stats->basis_mac+=(uint64_t)(length-1)*(dim-1);
    stats->recursion_mac+=(uint64_t)length*(length-1)/2;
    stats->exp_calls++;stats->sqrt_calls++;
    return 0;
}

size_t tetts_context_bytes(void){return sizeof(TetContext);}

int tetts_build_filters(const float *frames,int nframes,int dim,int bands,const float *basis,
                         int length,float *output){
    if(length<8||length>MAX_TAPS||dim<2||dim>MAX_DIM||bands<3||bands>MAX_BANDS)return -1;
    float causal[MAX_TAPS]={0};TetStats s={0};int stride=dim+bands+2;
    for(int i=0;i<nframes;i++){int result=build_filter(frames+i*stride,basis,dim,length,output+i*length,causal,&s);if(result)return result;}
    return 0;
}

int tetts_sources(const float *frames,int nframes,int dim,int bands,const float *bank,
                    int count,uint32_t seed,int harmonic_only,float *output,TetStats *stats){
    if(nframes<1||count<1||dim<2||dim>MAX_DIM||bands<3||bands>MAX_BANDS)return -1;
    TetContext c;initialize(&c,seed,bands);memset(stats,0,sizeof(*stats));int stride=dim+bands+2;
    double start=cpu_now();
    for(int pos=0;pos<count;pos+=HOP){
        int i=pos/HOP;if(i>=nframes)i=nframes-1;int j=i+1<nframes?i+1:i;
        int n=count-pos<HOP?count-pos:HOP;
        source_block(&c,frames+i*stride,frames+j*stride,dim,bands,bank,n,harmonic_only,stats);
        memcpy(output+pos,c.source,(size_t)n*sizeof(float));
    }
    stats->excitation_cpu_s=cpu_now()-start;stats->generated_samples=count;stats->context_bytes=sizeof(c);return 0;
}

int tetts_render(const float *frames,int nframes,int dim,int bands,const float *basis,const float *bank,
                  int length,int count,uint32_t seed,float pcm_gain,float *output,int16_t *pcm,TetStats *stats){
    if(nframes<1||count<1||length<8||length>MAX_TAPS||dim<2||dim>MAX_DIM||bands<3||bands>MAX_BANDS)return -1;
    TetContext c;initialize(&c,seed,bands);memset(stats,0,sizeof(*stats));int stride=dim+bands+2;
    double start=cpu_now();int result=build_filter(frames,basis,dim,length,c.filter_a,c.causal,stats);
    stats->filter_build_cpu_s+=cpu_now()-start;if(result)return result;
    for(int pos=0;pos<count;pos+=HOP){
        int i=pos/HOP;if(i>=nframes)i=nframes-1;int j=i+1<nframes?i+1:i;
        int n=count-pos<HOP?count-pos:HOP;
        start=cpu_now();result=build_filter(frames+j*stride,basis,dim,length,c.filter_b,c.causal,stats);
        stats->filter_build_cpu_s+=cpu_now()-start;if(result)return result;
        start=cpu_now();source_block(&c,frames+i*stride,frames+j*stride,dim,bands,bank,n,0,stats);
        stats->excitation_cpu_s+=cpu_now()-start;
        start=cpu_now();
        for(int s=0;s<n;s++){
            c.history[c.history_pos]=c.source[s];c.history[c.history_pos+length]=c.source[s];
            const float *past=c.history+c.history_pos+length;float ya=0,yb=0;
            for(int k=0;k<length;k++){
                float x=past[-k];ya+=c.filter_a[k]*x;yb+=c.filter_b[k]*x;
            }
            float alpha=(float)s/HOP;output[pos+s]=ya+(yb-ya)*alpha;
            if(!isfinite(output[pos+s]))return -3;
            c.history_pos++;if(c.history_pos==length)c.history_pos=0;
        }
        stats->fir_mac+=(uint64_t)2*length*n;stats->filtering_cpu_s+=cpu_now()-start;
        start=cpu_now();
        for(int s=0;s<n;s++){
            float x=output[pos+s]*pcm_gain*32768.f;
            if(x>=32768.f||x< -32768.f)stats->clipped_pcm++;
            x=clip(x,-32768.f,32767.f);pcm[pos+s]=(int16_t)lrintf(x);
        }
        stats->pcm_cpu_s+=cpu_now()-start;
        memcpy(c.filter_a,c.filter_b,(size_t)length*sizeof(float));
    }
    stats->generated_samples=count;stats->context_bytes=sizeof(c);return 0;
}
